'use client';

import React, { useState } from 'react';
import Button from '@/components/ui/Button';
import { Lock } from 'lucide-react';
import { useRouter } from 'next/navigation';

const AdminLogin = () => {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const router = useRouter();

    const handleLogin = (e) => {
        e.preventDefault();
        // Mock Login Logic
        if (email === 'admin@flight99.co.in' && password === 'admin') {
            localStorage.setItem('flight99_admin_auth', 'true'); // Simple auth
            router.push('/admin/dashboard');
        } else {
            alert('Invalid Credentials');
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50 px-4">
            <div className="max-w-md w-full bg-white p-8 rounded-2xl shadow-xl border border-gray-100">
                <div className="text-center mb-8">
                    <img src="/assets/logo.png" alt="FLIGHT99" className="h-12 w-auto mx-auto mb-4" />
                    <h2 className="text-2xl font-bold text-gray-900">Admin Portal</h2>
                    <p className="text-sm text-gray-500">Sign in to manage packages</p>
                </div>

                <form onSubmit={handleLogin} className="space-y-6">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Email Address</label>
                        <input
                            type="email"
                            required
                            className="input-premium w-full"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
                        <input
                            type="password"
                            required
                            className="input-premium w-full"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                        />
                    </div>

                    <Button type="submit" className="w-full flex justify-center gap-2" variant="primary">
                        <Lock className="w-4 h-4" /> Secure Login
                    </Button>
                </form>
            </div>
        </div>
    );
};

export default AdminLogin;
